import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

// Layout components
import Navbar from './components/Navbar/Navbar';
import Footer from './components/Footer/Footer';

// Pages
import Home from './pages/Home';
import Patents from './pages/Patents';
import PatentDetail from './pages/PatentDetail';
import PatentForm from './pages/PatentForm';
import Documents from './pages/Documents';
import DocumentDetail from './pages/DocumentDetail';
import DocumentForm from './pages/DocumentForm';
import Authors from './pages/Authors';
import AuthorDetail from './pages/AuthorDetail';
import AuthorForm from './pages/AuthorForm';
import Categories from './pages/Categories';
import Search from './pages/Search';
import Analytics from './pages/Analytics';

// Styles
import './App.css';

function App() {
  return (
    <Router>
      <div className="app">
        <Navbar />
        <main className="main-content">
          <Routes>
            {/* Home */}
            <Route path="/" element={<Home />} />
            
            {/* Patents */}
            <Route path="/patents" element={<Patents />} />
            <Route path="/patents/new" element={<PatentForm />} />
            <Route path="/patents/:id" element={<PatentDetail />} />
            <Route path="/patents/:id/edit" element={<PatentForm />} />
            
            {/* Documents */}
            <Route path="/documents" element={<Documents />} />
            <Route path="/documents/new" element={<DocumentForm />} />
            <Route path="/documents/:id" element={<DocumentDetail />} />
            <Route path="/documents/:id/edit" element={<DocumentForm />} />
            
            {/* Authors */}
            <Route path="/authors" element={<Authors />} />
            <Route path="/authors/new" element={<AuthorForm />} />
            <Route path="/authors/:id" element={<AuthorDetail />} />
            <Route path="/authors/:id/edit" element={<AuthorForm />} />
            
            {/* Categories */}
            <Route path="/categories" element={<Categories />} />
            
            {/* Search */}
            <Route path="/search" element={<Search />} />
            
            {/* Analytics */}
            <Route path="/analytics" element={<Analytics />} />
            
            {/* 404 */}
            <Route path="*" element={<NotFound />} />
          </Routes>
        </main>
        <Footer />
        
        <ToastContainer
          position="bottom-right"
          autoClose={3000}
          hideProgressBar={false}
          newestOnTop
          closeOnClick
          rtl={false}
          pauseOnFocusLoss
          draggable
          pauseOnHover
          theme="light"
        />
      </div>
    </Router>
  );
}

// 404 Page
const NotFound = () => (
  <div className="not-found">
    <div className="container">
      <h1>404</h1>
      <h2>Сторінку не знайдено</h2>
      <p>Сторінка, яку ви шукаєте, не існує або була переміщена.</p>
      <a href="/" className="btn btn-primary">На головну</a>
    </div>
  </div>
);

export default App;
